package afero.model;

public class Cest {
	
	private String nrCest;
	private String dsCest;
	
	
	public Cest() {
		super();
		// TODO Auto-generated constructor stub
	}


	public Cest(String nrCest, String dsCest) {
		super();
		this.nrCest = nrCest;
		this.dsCest = dsCest;
	}


	public String getNrCest() {
		return nrCest;
	}


	public void setNrCest(String nrCest) {
		this.nrCest = nrCest;
	}


	public String getDsCest() {
		return dsCest;
	}


	public void setDsCest(String dsCest) {
		this.dsCest = dsCest;
	}
	
	

}
